import React, { useEffect, useState } from "react";
import Swal from "sweetalert2";
import { Lock, ShieldCheck } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "../ui/dialog";
import { Button } from "../ui/button";
import roleService from "../../services/role.service";

const MODULE_LABELS = {
  usuarios: "Usuarios",
  empresas: "Empresas",
  roles: "Roles y Permisos",
};

const emptyForm = {
  name: "",
  description: "",
  is_company_scoped: true,
  permission_ids: [],
};

export const RoleFormModal = ({ open, onClose, role, permissions, onSaved }) => {
  const [form, setForm] = useState(emptyForm);
  const [submitting, setSubmitting] = useState(false);
  const [errors, setErrors] = useState({});

  const isEditing = !!role;
  const isSystemRole = !!role?.is_system;

  useEffect(() => {
    if (open) {
      if (role) {
        setForm({
          name: role.name,
          description: role.description || "",
          is_company_scoped: role.is_company_scoped,
          permission_ids: role.permissions.map((p) => p.id),
        });
      } else {
        setForm(emptyForm);
      }
      setErrors({});
    }
  }, [open, role]);

  const togglePermission = (permissionId) => {
    setForm((prev) => {
      const has = prev.permission_ids.includes(permissionId);
      return {
        ...prev,
        permission_ids: has
          ? prev.permission_ids.filter((id) => id !== permissionId)
          : [...prev.permission_ids, permissionId],
      };
    });
  };

  const toggleModule = (modulePermissions, allSelected) => {
    setForm((prev) => {
      const moduleIds = modulePermissions.map((p) => p.id);
      const permission_ids = allSelected
        ? prev.permission_ids.filter((id) => !moduleIds.includes(id))
        : [...new Set([...prev.permission_ids, ...moduleIds])];
      return { ...prev, permission_ids };
    });
  };

  const validate = () => {
    const newErrors = {};
    if (!form.name.trim()) {
      newErrors.name = "El nombre es obligatorio";
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validate()) return;

    setSubmitting(true);
    try {
      const payload = {
        name: form.name.trim(),
        description: form.description.trim() || null,
        is_company_scoped: form.is_company_scoped,
        permission_ids: form.permission_ids,
      };

      if (isEditing) {
        await roleService.updateRole(role.id, payload);
      } else {
        await roleService.createRole(payload);
      }

      onSaved();
      onClose();
    } catch (err) {
      const detail = err.response?.data?.detail;
      Swal.fire({
        icon: "error",
        title: isEditing ? "No se pudo actualizar el rol" : "No se pudo crear el rol",
        text: detail || "Intenta nuevamente",
        confirmButtonColor: "#16a34a",
      });
    } finally {
      setSubmitting(false);
    }
  };

  // Agrupa el catálogo de permisos por módulo
  const permissionsByModule = permissions.reduce((acc, p) => {
    acc[p.module] = acc[p.module] || [];
    acc[p.module].push(p);
    return acc;
  }, {});

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="sm:max-w-lg max-h-[85vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <ShieldCheck className="w-5 h-5 text-green-600" />
            {isEditing ? "Editar rol" : "Nuevo rol"}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-5 mt-2">
          {isSystemRole && (
            <div className="flex items-start gap-2 bg-amber-50 border border-amber-200 text-amber-800 text-xs rounded-lg px-3 py-2">
              <Lock className="w-4 h-4 mt-0.5 flex-shrink-0" />
              <span>
                Este es un rol de sistema: no se puede renombrar ni cambiar su
                alcance de empresas, pero sí ajustar sus permisos.
              </span>
            </div>
          )}

          <div>
            <label className="block text-sm font-medium mb-1.5 text-gray-700">
              Nombre del rol
            </label>
            <input
              type="text"
              value={form.name}
              disabled={isSystemRole}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
              placeholder="Ej. Coordinador Zona Sur"
              className="w-full px-4 py-2.5 rounded-lg border border-gray-300 bg-white text-sm focus:border-green-500 focus:ring-2 focus:ring-green-200 outline-none transition-all disabled:bg-gray-100 disabled:text-gray-500"
            />
            {errors.name && <p className="text-xs text-red-600 mt-1">{errors.name}</p>}
          </div>

          <div>
            <label className="block text-sm font-medium mb-1.5 text-gray-700">
              Descripción
            </label>
            <textarea
              value={form.description}
              onChange={(e) => setForm({ ...form, description: e.target.value })}
              rows={2}
              placeholder="¿Para qué se usa este rol?"
              className="w-full px-4 py-2.5 rounded-lg border border-gray-300 bg-white text-sm focus:border-green-500 focus:ring-2 focus:ring-green-200 outline-none transition-all"
            />
          </div>

          <div className="flex items-start gap-3 bg-gray-50 border border-gray-200 rounded-lg px-4 py-3">
            <input
              id="is_company_scoped"
              type="checkbox"
              checked={form.is_company_scoped}
              disabled={isSystemRole}
              onChange={(e) =>
                setForm({ ...form, is_company_scoped: e.target.checked })
              }
              className="mt-0.5 w-4 h-4 accent-green-600 disabled:opacity-50"
            />
            <label htmlFor="is_company_scoped" className="text-sm text-gray-700">
              <span className="font-medium">Acotado a empresas asignadas</span>
              <p className="text-xs text-gray-500 mt-0.5">
                Si está activo, los usuarios con este rol solo verán las
                empresas que se les asignen individualmente. Si está
                desactivado, verán todas las empresas del sistema.
              </p>
            </label>
          </div>

          <div>
            <p className="text-sm font-medium text-gray-700 mb-2">Permisos</p>
            <div className="space-y-4 max-h-64 overflow-y-auto border border-gray-200 rounded-lg p-3">
              {Object.entries(permissionsByModule).map(([module, modulePermissions]) => {
                const allSelected = modulePermissions.every((p) =>
                  form.permission_ids.includes(p.id)
                );
                return (
                  <div key={module}>
                    <div className="flex items-center justify-between mb-1.5">
                      <p className="text-xs font-bold uppercase tracking-wide text-gray-500">
                        {MODULE_LABELS[module] || module}
                      </p>
                      <button
                        type="button"
                        onClick={() => toggleModule(modulePermissions, allSelected)}
                        className="text-xs text-green-600 hover:underline"
                      >
                        {allSelected ? "Quitar todos" : "Seleccionar todos"}
                      </button>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-1.5">
                      {modulePermissions.map((permission) => (
                        <label
                          key={permission.id}
                          className="flex items-start gap-2 text-sm text-gray-700 cursor-pointer"
                        >
                          <input
                            type="checkbox"
                            checked={form.permission_ids.includes(permission.id)}
                            onChange={() => togglePermission(permission.id)}
                            className="mt-0.5 w-4 h-4 accent-green-600"
                          />
                          <span>
                            {permission.name}
                            {permission.description && (
                              <span className="block text-xs text-gray-400">
                                {permission.description}
                              </span>
                            )}
                          </span>
                        </label>
                      ))}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="flex justify-end gap-3 pt-2">
            <Button type="button" variant="outline" onClick={onClose}>
              Cancelar
            </Button>
            <Button
              type="submit"
              disabled={submitting}
              className="bg-green-600 hover:bg-green-700 text-white disabled:opacity-60"
            >
              {submitting ? "Guardando..." : isEditing ? "Guardar cambios" : "Crear rol"}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default RoleFormModal;
